import{_ as r,c as e,d as l,a0 as i}from"./chunks/framework.CNvduE9I.js";const d=JSON.parse('{"title":"微架构安全入门","description":"从缓存、取指和执行学起，再沿共享资源与瞬态执行等路线分析微架构安全问题。","frontmatter":{"title":"微架构安全入门","description":"从缓存、取指和执行学起，再沿共享资源与瞬态执行等路线分析微架构安全问题。","date":"2026-11-25","tags":["微架构安全","导论","Spectre","Meltdown"],"bookTitle":"微架构安全"},"headers":[],"relativePath":"posts/microarch-00-intro.md","filePath":"posts/microarch-00-intro.md"}'),h={name:"posts/microarch-00-intro.md"};function c(t,a,o,m,s,n){return e(),l("div",null,a[0]||(a[0]=[i('<p>两个线程各自修改不同的计数器，为什么还会等待对方？一条指令最终没有提交，为什么它先前发出的请求仍可能改变缓存？这两个问题都要追踪程序结果之外的硬件状态。前者可以从缓存行和写权限讲起，后者需要理解预测、异常和指令退休。</p><p>微架构是指实现指令集的软件可见规则所用的硬件组织。处理器可以保存数据副本、预测后续访存和下一条指令的地址，也可以先执行暂时不必交付结果的操作。这些行为平时用于提高速度。某些内部状态会影响之后的访问时间。当受保护的信息能够改变这些状态时，时间就可能成为分析安全边界的一部分。</p><h2 id="本书怎样展开" tabindex="-1">本书怎样展开 <a class="header-anchor" href="#本书怎样展开" aria-label="Permalink to &quot;本书怎样展开&quot;">​</a></h2><p><strong>Spectre</strong> 原始研究的一条路径从错误的控制流预测出发。处理器沿着预测路径执行了一段操作，发现方向不对后丢弃结果。<strong>Meltdown</strong> 原始研究则表明，在论文讨论的受影响处理器上，一次在架构上会被权限拒绝的加载，可能在报告异常前影响后续的内部操作。这两个例子共同引出一个问题：如果相关指令的结果没有正式生效，哪些内部状态还可能使它的影响留到后来？</p><p>读者应会基本的十六进制运算，知道寄存器、地址和数组的含义。通读可以按下面的目录顺序。带着具体问题查阅时，可以从三条路线进入。</p><ul><li><strong>追踪一笔访存。</strong> 从<a href="./microarch-01b-cache-mapping.html#cache-lookup">缓存怎样查找和替换一行</a>找出它所在的组和路。未命中时，跟着 <a href="./microarch-01a-mshr.html#mshr-trace">MSHR 的读请求</a>看下一级返回，再看<a href="./microarch-01e-cache-stores.html#write-back-buffer">脏行怎样移交给下一级</a>。</li><li><strong>解释两个程序同时运行时为什么变慢。</strong> 先读<a href="./microarch-01f-coherence.html#mesi-upgrade">一致性中的写权限交接</a>，再看<a href="./microarch-06b-memory-queue.html#memory-row">内存控制器的行调度</a>。这两篇分别给出缓存行交接和 DRAM 服务顺序的例题，可以结合<a href="./microarch-04a-measurement.html#pmu-window">计时窗口</a>确定测量覆盖了哪段等待。</li><li><strong>判断指令为何先执行、后来又撤销。</strong> 从<a href="./microarch-02a-translation.html#sv39-permissions">页表权限</a>和<a href="./microarch-03-execution.html#ooo-retire">乱序退休</a>学起，再看<a href="./microarch-03a-fetch-prediction.html#predict-recovery">分支预测走错以后怎样恢复</a>。有了这些先修知识，再读瞬态执行相关内容。</li></ul><h2 id="book-contents" tabindex="-1">目录 <a class="header-anchor" href="#book-contents" aria-label="Permalink to &quot;目录 {#book-contents}&quot;">​</a></h2><h3 id="第一章-访存局部性与高速缓存" tabindex="-1">第一章　访存局部性与高速缓存 <a class="header-anchor" href="#第一章-访存局部性与高速缓存" aria-label="Permalink to &quot;第一章　访存局部性与高速缓存&quot;">​</a></h3><p>先沿字节地址算出缓存组、标记和行内偏移，再按访问次序判断哪些块会留到下一次读取。数组扫描先练习数块，矩阵例题再加上组相联的限制。读到两张矩阵时，要把同一循环中所有落到该组的块都计入。</p><p>随后跟一笔未命中走到 MSHR，分别追踪读写权限、要取得的旧字节和随后写回的数据。两笔写能否合并，取决于发包前已经覆盖哪些字节，以及其间是否有读请求。学完单核路径，再把同一条行放进两个核的私有缓存，推导失效确认与最新数据的去向，最后用计数器例题定位伪共享的字段。</p><ol><li><a href="./microarch-01-cache.html">缓存行与局部性</a><ul><li><a href="./microarch-01-cache.html#locality-cross-line">一次加载跨过缓存行边界时</a></li><li><a href="./microarch-01-cache.html#locality-second-pass">同一个数组扫描两遍，为什么第二遍还要取行</a></li></ul></li><li><a href="./microarch-01b-cache-mapping.html">缓存怎样查找和替换一行</a><ul><li><a href="./microarch-01b-cache-mapping.html#cache-tree-plru">四路树形替换怎样选出牺牲行</a></li><li><a href="./microarch-01b-cache-mapping.html#cache-vipt">一级缓存怎样与地址翻译并行</a></li><li><a href="./microarch-01b-cache-mapping.html#cache-vipt-alias-store">同一份数据有两个虚拟地址时，写入改了哪一行</a></li><li><a href="./microarch-01b-cache-mapping.html#cache-vipt-coloring">操作系统怎样让两个映射落到同一组</a></li></ul></li><li><a href="./microarch-01d-cache-traversal.html">矩阵按行读和按列读的缓存开销</a><ul><li><a href="./microarch-01d-cache-traversal.html#matrix-stride-sets">把行跨度换成组号</a></li><li><a href="./microarch-01d-cache-traversal.html#matrix-set-period">组号绕一圈要多少行</a></li><li><a href="./microarch-01d-cache-traversal.html#matrix-row-tiles">不改矩阵布局，也能减少按列读取的未命中</a></li><li><a href="./microarch-01d-cache-traversal.html#matrix-two-stream-tiles">同一个循环读两张矩阵，为什么每批只能留四行</a></li></ul></li><li><a href="./microarch-01a-mshr.html">缓存未命中后如何合并请求</a><ul><li><a href="./microarch-01a-mshr.html#mshr-capacity-trace">沿主例数一数槽位</a></li><li><a href="./microarch-01a-mshr.html#mshr-read-then-write">读请求发出后，同一行又来了写请求</a></li><li><a href="./microarch-01a-mshr.html#mshr-write-byte-trace">取得写权限后，哪些字节真正变了</a></li><li><a href="./microarch-01a-mshr.html#mshr-send-retry">下一级拒收以后，重试还会发原来的包吗</a></li><li><a href="./microarch-01a-mshr.html#mshr-split-load">跨行加载的两部分可以各走一条路</a></li></ul></li><li><a href="./microarch-01e-cache-stores.html">写入缓存后，数据什么时候送到下一级</a><ul><li><a href="./microarch-01e-cache-stores.html#store-whole-line">两笔局部写什么时候能省去整行读取</a></li><li><a href="./microarch-01e-cache-stores.html#write-back-retry">写回被拒绝后，同一行的读取要等到哪一步</a></li><li><a href="./microarch-01e-cache-stores.html#writeback-address">被替换的行怎样重新组成写回地址</a></li><li><a href="./microarch-01e-cache-stores.html#write-back-reserve">写缓冲报满时，已经在途的填充怎么办</a></li></ul></li><li><a href="./microarch-01f-coherence.html">缓存一致性：两个核怎样读到最新值</a><ul><li><a href="./microarch-01f-coherence.html#mesi-ack-arrival">失效确认比目录回复先到怎么办</a></li><li><a href="./microarch-01f-coherence.html#mesi-stale-sharer">目录记着共享者，它却已经换出了这条行</a></li><li><a href="./microarch-01f-coherence.html#moesi-owned">MOESI 怎样处理多个核读取同一条脏行</a></li><li><a href="./microarch-01f-coherence.html#coherence-store-buffering">两个地址都一致，为什么还会读到两个旧值</a></li><li><a href="./microarch-01f-coherence.html#coherence-fence-order">怎样证明栅栏排除了两个旧值</a></li><li><a href="./microarch-01f-coherence.html#coherence-release-acquire">生产者怎样用就绪标志发布数据</a></li><li><a href="./microarch-01f-coherence.html#coherence-dma">网卡收包后，CPU 何时能读到新数据</a></li></ul></li><li><a href="./microarch-01g-false-sharing.html">两个线程改不同字段，为什么缓存行还会来回传</a><ul><li><a href="./microarch-01g-false-sharing.html#sharing-alignment">字段间隔和起始地址怎样一起决定行号</a></li><li><a href="./microarch-01g-false-sharing.html#sharing-array-stride">数组已经对齐，为什么不同元素仍会共用一行</a></li><li><a href="./microarch-01g-false-sharing.html#sharing-four-workers">四个线程怎样分工，才不会共写一行</a></li><li><a href="./microarch-01g-false-sharing.html#sharing-read-write">只读字段也会被迫重新加载</a></li></ul></li></ol><h3 id="第二章-硬件预取器" tabindex="-1">第二章　硬件预取器 <a class="header-anchor" href="#第二章-硬件预取器" aria-label="Permalink to &quot;第二章　硬件预取器&quot;">​</a></h3><p>先从三次访问算出步长和候选地址，再跟踪候选怎样过页、排队和填充。随后到 RTL 一节，逐拍看缓存接收与拒绝怎样改变暂存槽。</p><ol><li><a href="./microarch-02-prefetch.html">硬件预取器怎样工作</a><ul><li><a href="./microarch-02-prefetch.html#prefetch-requestor-tables">两个请求者执行同一条加载时怎样选表</a></li><li><a href="./microarch-02-prefetch.html#prefetch-reverse">访问方向反转后，步长表怎样重新学习</a></li><li><a href="./microarch-02-prefetch.html#prefetch-mshr-reserve">MSHR 还有空项，为什么预取仍要等</a></li><li><a href="./microarch-02-prefetch.html#prefetch-pollution">预取到正确的行，为什么未命中数没降</a></li><li><a href="./microarch-02-prefetch.html#prefetch-dirty-traffic">综合题｜一次提前填充会多传多少数据</a></li></ul></li><li><a href="./microarch-02d-prefetch-rtl.html">预取器和数据缓存怎样握手</a><ul><li><a href="./microarch-02d-prefetch-rtl.html#rtl-snoop-retry">核心请求重试时，步长器在哪一拍看到地址</a></li><li><a href="./microarch-02d-prefetch-rtl.html#rtl-interleaved-streams">两条访问流交错时，为什么历史计数还能上升</a></li><li><a href="./microarch-02d-prefetch-rtl.html#rtl-trace">逐拍跟踪一条被拒绝的请求</a></li><li><a href="./microarch-02d-prefetch-rtl.html#rtl-retry-priority">P 重试时，核心恰好又有请求</a></li></ul></li></ol><h3 id="第三章-地址翻译" tabindex="-1">第三章　地址翻译 <a class="header-anchor" href="#第三章-地址翻译" aria-label="Permalink to &quot;第三章　地址翻译&quot;">​</a></h3><p>先用一个地址走完三级页表，再区分 TLB 保存的最终映射和<a href="./microarch-02a-translation.html#sv39-walk-cache">页表遍历缓存保存的中间结果</a>。两个核都用过同一个映射时，沿着页表写入、本地同步和远端确认，判断何时可以回收旧页。</p><ol><li><a href="./microarch-02a-translation.html">处理器怎样用页表和 TLB 翻译地址</a><ul><li><a href="./microarch-02a-translation.html#sv39-pmp-tor">物理地址怎样匹配一条 PMP 规则</a></li><li><a href="./microarch-02a-translation.html#sv39-sum-mxr">监管者怎样读取用户页</a></li><li><a href="./microarch-02a-translation.html#sv39-ad-bits">同一页的 A、D 位怎样变化</a></li><li><a href="./microarch-02a-translation.html#sv39-tlb-reach">换成大页以后，哪些读取还要遍历</a></li><li><a href="./microarch-02a-translation.html#sv39-asid-reuse">ASID 交给另一套页表时，要清掉哪些翻译</a></li><li><a href="./microarch-02a-translation.html#sv39-two-stage">虚拟机里的加载要查几次页表</a></li><li><a href="./microarch-02a-translation.html#sv39-two-stage-model">用 C 逐笔数出两阶段的表项读取</a></li><li><a href="./microarch-02a-translation.html#iommu-device-translation">设备怎样用 IOMMU 翻译 DMA 地址</a></li></ul></li></ol><h3 id="第四章-指令执行与分支预测" tabindex="-1">第四章　指令执行与分支预测 <a class="header-anchor" href="#第四章-指令执行与分支预测" aria-label="Permalink to &quot;第四章　指令执行与分支预测&quot;">​</a></h3><p>先跟踪一条指令从执行到退休，再用存储队列例题，判断两个不同的虚拟地址何时会<a href="./microarch-03d-load-store.html#lsu-address-alias">匹配同一笔存储</a>，以及地址迟到时核心怎样重执行。把视线移到前端后，沿同一次取指学习目标、方向和历史各自怎样参与预测，再用同一个分支例题区分重定向、历史恢复与方向表训练。</p><ol><li><a href="./microarch-03-execution.html">乱序执行怎样按程序顺序退休</a><ul><li><a href="./microarch-03-execution.html#ooo-issue-wakeup">发射队列怎样唤醒等数据的加法</a></li><li><a href="./microarch-03-execution.html#ooo-issue-ports">两个发射端口空着，为什么只发出一条指令</a></li><li><a href="./microarch-03-execution.html#ooo-prf-pressure">ROB 还有空位，为什么新指令仍进不去</a></li><li><a href="./microarch-03-execution.html#ooo-map-rollback">用旧目的编号逐项回滚</a></li><li><a href="./microarch-03-execution.html#ooo-oldest-exception">两条加载都出错时，先报告哪一条</a></li></ul></li><li><a href="./microarch-03d-load-store.html">加载怎样从存储队列拿到数据</a><ul><li><a href="./microarch-03d-load-store.html#lsu-partial">较新的存储只覆盖加载的一部分</a></li><li><a href="./microarch-03d-load-store.html#lsu-store-nack">存储已经退休，缓存拒绝后怎样重发</a></li><li><a href="./microarch-03d-load-store.html#lsu-load-load-order">两条加载读同一个字，为什么也要互相检查</a></li></ul></li><li><a href="./microarch-03a-fetch-prediction.html">分支预测器怎样决定下一次取指</a><ul><li><a href="./microarch-03a-fetch-prediction.html#predict-btb-conflict">索引相同，标记不同会怎样</a></li><li><a href="./microarch-03a-fetch-prediction.html#predict-ras-capacity">两项预测栈遇到三层调用</a></li><li><a href="./microarch-03a-fetch-prediction.html#predict-ras-repair">分支改道时，返回地址栈要恢复什么</a></li><li><a href="./microarch-03a-fetch-prediction.html#predict-rsb">x86 的 RSB 与程序栈各保存什么</a></li><li><a href="./microarch-03a-fetch-prediction.html#predict-alias">两个不同上下文查到同一个计数器</a></li><li><a href="./microarch-03a-fetch-prediction.html#predict-tage-selection">多张方向表同时命中，怎样选出预测</a></li><li><a href="./microarch-03a-fetch-prediction.html#predict-bhb">分支历史怎样参与间接跳转目标选择</a></li></ul></li></ol><h3 id="第五章-计时与证据" tabindex="-1">第五章　计时与证据 <a class="header-anchor" href="#第五章-计时与证据" aria-label="Permalink to &quot;第五章　计时与证据&quot;">​</a></h3><p>让两种访问顺序走同一个求和循环，先分别量程序整体和求和区间，再核对 PMU 记录的事件与实际计数时长。随后从共享缓存行和 TLB 组两种观测对象出发，逐步追踪占用、目标访问、重载与计时，判断每种读数能支持哪一步结论，以及页级活动的时间顺序怎样补足单纯组计数的不足。</p><ol><li><a href="./microarch-04a-measurement.html">用计时和计数器分析访存</a><ul><li><a href="./microarch-04a-measurement.html#pmu-task-vs-cpu">线程换了 CPU，计数跟着谁走</a></li><li><a href="./microarch-04a-measurement.html#pmu-delta">分两段读取时，先取差值再换算</a></li><li><a href="./microarch-04a-measurement.html#pmu-group-window">两个事件一起计数，能代表整段执行吗</a></li><li><a href="./microarch-04a-measurement.html#pmu-sampling-skid">为什么样本会落在加法指令上</a></li><li><a href="./microarch-04a-measurement.html#pmu-miss-overlap">同样四次未命中，为什么有时只等一轮</a></li></ul></li><li><a href="./microarch-04b-observation.html">一次缓存计时能说明什么</a><ul><li><a href="./microarch-04b-observation.html#evidence-base-rate">访问很少发生时，快读数还有多大把握</a></li><li><a href="./microarch-04b-observation.html#evidence-prime-probe">不共享数据页，怎样观察同一个缓存组</a></li><li><a href="./microarch-04b-observation.html#evidence-channel-types">侧信道与隐蔽通道怎样区分</a></li></ul></li><li><a href="./microarch-04i-tlb-observation.html">TLB 命中与未命中怎样留下访问痕迹</a><ul><li><a href="./microarch-04i-tlb-observation.html#tlb-four-way-eviction">用四路模型算出一次 TLB 驱逐</a></li><li><a href="./microarch-04i-tlb-observation.html#tlb-intel-measurement">两代 Intel 处理器的 TLB 结构实测</a></li><li><a href="./microarch-04i-tlb-observation.html#tlb-walk-events">二级 TLB 命中和页表遍历怎样分别计数</a></li><li><a href="./microarch-04i-tlb-observation.html#tlb-tagged-competition">地址空间标签怎样与替换竞争同时存在</a></li></ul></li></ol><h3 id="第六章-共享资源与隔离" tabindex="-1">第六章　共享资源与隔离 <a class="header-anchor" href="#第六章-共享资源与隔离" aria-label="Permalink to &quot;第六章　共享资源与隔离&quot;">​</a></h3><p>把两个工作负载放在一起，先查它们共用哪些结构。沿末级缓存的数据阵列和探测过滤器，分别判断哪个槽用尽、哪一份私有副本需要撤销。请求继续走到内存控制器时，再判断它是在等入队、等打开行，还是等通道切回读方向。之后从控制组和缓存域查 CAT 掩码，推导新块能填到哪里。最后从两个逻辑 CPU 的运行队列算出同核配对，看看有任务在排队时为何仍可能空闲。</p><ol><li><a href="./microarch-06a-shared-cache.html">不同的数据为什么会在末级缓存里互相挤掉</a><ul><li><a href="./microarch-06a-shared-cache.html#llc-dirty-victim">如果被换出的行在私有缓存里已经改过</a></li><li><a href="./microarch-06a-shared-cache.html#llc-snoop-filter">LLC 还有空路，为什么私有副本也可能被撤销</a></li><li><a href="./microarch-06a-shared-cache.html#llc-miss-source">LLC 未命中是否等于 DRAM 读取？</a></li></ul></li><li><a href="./microarch-06b-memory-queue.html">未命中次数相同，为什么内存等待更长</a><ul><li><a href="./microarch-06b-memory-queue.html#memory-split-bank-response">一个读包跨两个存储体，要等哪一半</a></li><li><a href="./microarch-06b-memory-queue.html#memory-bank-overlap">两个存储体怎样共用一条数据总线</a></li><li><a href="./microarch-06b-memory-queue.html#memory-write-drain">写队列积满到什么程度，读请求要让路</a></li><li><a href="./microarch-06b-memory-queue.html#memory-refresh">刷新怎样打断一次本来会命中打开行的读取</a></li><li><a href="./microarch-06b-memory-queue.html#memory-write-queue-read">写队列覆盖了部分读包，还要发几次列读</a></li><li><a href="./microarch-06b-memory-queue.html#memory-forward-admission">写队列能满足一部分，入队检查为何仍可能失败</a></li></ul></li><li><a href="./microarch-06c-cat.html">划分末级缓存的路能隔离什么</a><ul><li><a href="./microarch-06c-cat.html#cat-sets">掩码里的路怎样分布在各个组中</a></li><li><a href="./microarch-06c-cat.html#cat-cdp">同一个任务取指和读数据，分别用哪份掩码</a></li><li><a href="./microarch-06c-cat.html#cat-rmid-occupancy">任务换组后，旧组的占用为什么还在</a></li><li><a href="./microarch-06c-cat.html#cat-mbm">把两个域的流量读数换成带宽</a></li></ul></li><li><a href="./microarch-06d-core-scheduling.html">同核多线程怎样安排任务</a><ul><li><a href="./microarch-06d-core-scheduling.html#core-ipi-handoff">选好新配对以后，旧任务什么时候停下</a></li><li><a href="./microarch-06d-core-scheduling.html#core-kernel-context">同组任务进入内核时，另一侧在做什么</a></li><li><a href="./microarch-06d-core-scheduling.html#core-migration">同一个任务迁移后，观察范围怎样变化</a></li><li><a href="./microarch-06d-core-scheduling.html#core-throughput">空出一侧后，吞吐会少一半吗</a></li></ul></li></ol><h3 id="第七章-dram-扰动与硬件错误" tabindex="-1">第七章　DRAM 扰动与硬件错误 <a class="header-anchor" href="#第七章-dram-扰动与硬件错误" aria-label="Permalink to &quot;第七章　DRAM 扰动与硬件错误&quot;">​</a></h3><p>先从 DRAM 单元、字线、位线和行缓冲的结构入手，再把 ACT、READ、PRE 与刷新放进同一条命令序列。用一个 bank 的教学模型区分列读和行激活，最后沿缓存、物理地址映射、TRR 与 ECC 逐项检查 Rowhammer 的成立条件和防护边界。</p><ol><li><a href="./microarch-07a-rowhammer.html">DRAM 行被反复打开时，邻近数据为何会翻转</a><ul><li><a href="./microarch-07a-rowhammer.html#rowhammer-commands">ACT、READ、PRE 改变的是不同状态</a></li><li><a href="./microarch-07a-rowhammer.html#rowhammer-c-model">用 C 模型区分列读和行激活</a></li><li><a href="./microarch-07a-rowhammer.html#rowhammer-mitigation">防护要对准激活次数、邻行和错误模式</a></li><li><a href="./microarch-07a-rowhammer.html#rowhammer-ecc-codeword">ECC 怎样知道该翻回哪一位</a></li><li><a href="./microarch-07a-rowhammer.html#rowhammer-ecc-scrub">读到的数据已经纠正，为什么还要写回</a></li></ul></li></ol><h3 id="第八章-瞬态执行" tabindex="-1">第八章　瞬态执行 <a class="header-anchor" href="#第八章-瞬态执行" aria-label="Permalink to &quot;第八章　瞬态执行&quot;">​</a></h3><p>先分别读清 Spectre v1 的边界检查和 Meltdown 的权限异常，再沿完整 C 代码逐段追踪训练、瞬态访问、缓存编码和结果恢复。之后再看页表隔离和其他变体，区分漏洞机制、缓解措施与适用范围。</p><ol><li><a href="./microarch-04d-spectre-v1.html">Spectre v1 中的边界检查为何会被越过</a></li><li><a href="./microarch-04g-spectre-v1-source.html">Spectre v1 源码讲解</a></li><li><a href="./microarch-04e-meltdown.html">Meltdown 中的越权加载如何影响后续指令</a></li><li><a href="./microarch-04h-meltdown-source.html">Meltdown 源码讲解</a></li><li><a href="./microarch-04f-page-table-isolation.html">进入内核时怎样切换页表</a></li><li><a href="./microarch-04c-variants.html">Spectre 变体中的分支与访存推测</a></li></ol><p>读到例题时，先按题设复算一次，再对照手册确认哪些条件可以用于具体处理器。更换行长、替换策略或观察条件时，可以用原来的推理方法重新计算。 <a href="./microarch-05-sources.html">微架构安全学习资料</a></p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://spectreattack.com/spectre.pdf" target="_blank" rel="noreferrer">Spectre 原论文</a></li><li><a href="https://meltdownattack.com/meltdown.pdf" target="_blank" rel="noreferrer">Meltdown 原论文</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-01-cache.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>缓存行与局部性</strong></span></a></p></nav>',36)]))}const p=r(h,[["render",c]]);export{d as __pageData,p as default};
